<?php

namespace App\Bookshop;

use Doctrine\DBAL\Connection;

/**
 * Read and simple write queries over the existing bookshop tables.
 */
final class BookshopStore
{
    public function __construct(private readonly Connection $connection)
    {
    }

    /**
     * @param array{title: ?string, author: ?string, priceCents: array<string, string>, publishedAt: array<string, string>, inStock: ?bool} $filters
     * @param array<string, string>                                                                                                        $orders  column => ASC|DESC
     *
     * @return array{items: list<array<string, mixed>>, total: int}
     */
    public function searchBooks(array $filters, array $orders, int $page, int $perPage): array
    {
        $where = ['b.published = true'];
        $params = [];

        if (null !== $filters['title']) {
            $where[] = 'strpos(lower(b.title), lower(:title)) > 0';
            $params['title'] = $filters['title'];
        }
        if (null !== $filters['author']) {
            $where[] = 'a.name = :author';
            $params['author'] = $filters['author'];
        }
        if (isset($filters['priceCents']['gte'])) {
            $where[] = 'b.price_cents >= CAST(:priceGte AS numeric)';
            $params['priceGte'] = $filters['priceCents']['gte'];
        }
        if (isset($filters['priceCents']['lte'])) {
            $where[] = 'b.price_cents <= CAST(:priceLte AS numeric)';
            $params['priceLte'] = $filters['priceCents']['lte'];
        }
        if (isset($filters['publishedAt']['after'])) {
            $where[] = 'b.published_at >= CAST(:publishedAfter AS date)';
            $params['publishedAfter'] = $filters['publishedAt']['after'];
        }
        if (isset($filters['publishedAt']['before'])) {
            $where[] = 'b.published_at <= CAST(:publishedBefore AS date)';
            $params['publishedBefore'] = $filters['publishedAt']['before'];
        }
        if (true === $filters['inStock']) {
            $where[] = 'b.stock > 0';
        } elseif (false === $filters['inStock']) {
            $where[] = 'b.stock = 0';
        }

        $from = 'FROM book b JOIN author a ON a.id = b.author_id WHERE '.implode(' AND ', $where);
        $total = (int) $this->connection->fetchOne('SELECT COUNT(*) '.$from, $params);

        $offset = ($page - 1) * $perPage;
        if ($offset >= $total) {
            return ['items' => [], 'total' => $total];
        }

        $sort = [];
        foreach ($orders as $column => $direction) {
            $sort[] = $column.' '.$direction;
        }
        $sort[] = 'b.id ASC';

        $items = $this->connection->fetchAllAssociative(
            'SELECT b.id, b.title, b.price_cents, b.published_at, b.stock, b.published, a.id AS author_id, a.name AS author_name '
            .$from.' ORDER BY '.implode(', ', $sort).' LIMIT '.$perPage.' OFFSET '.$offset,
            $params,
        );

        return ['items' => $items, 'total' => $total];
    }

    /**
     * @return array<string, mixed>|null
     */
    public function findBook(int $id, bool $publishedOnly): ?array
    {
        $row = $this->connection->fetchAssociative(
            'SELECT b.id, b.title, b.price_cents, b.published_at, b.stock, b.published, a.id AS author_id, a.name AS author_name '
            .'FROM book b JOIN author a ON a.id = b.author_id WHERE b.id = :id'.($publishedOnly ? ' AND b.published = true' : ''),
            ['id' => $id],
        );

        return false === $row ? null : $row;
    }

    /**
     * @param array<string, int|string> $changes column => new value
     */
    public function updateBook(int $id, array $changes): void
    {
        $set = [];
        $params = ['id' => $id];
        foreach ($changes as $column => $value) {
            $set[] = $column.' = :'.$column;
            $params[$column] = $value;
        }
        if ([] !== $set) {
            $this->connection->executeStatement('UPDATE book SET '.implode(', ', $set).' WHERE id = :id', $params);
        }
    }

    public function countAuthors(): int
    {
        return (int) $this->connection->fetchOne('SELECT COUNT(*) FROM author');
    }

    /**
     * @return list<array<string, mixed>>
     */
    public function authorsPage(int $offset, int $limit): array
    {
        return $this->connection->fetchAllAssociative(
            'SELECT a.id, a.name, (SELECT COUNT(*) FROM book b WHERE b.author_id = a.id AND b.published = true) AS published_books '
            .'FROM author a ORDER BY a.id LIMIT '.$limit.' OFFSET '.$offset,
        );
    }

    /**
     * @return array<string, mixed>|null
     */
    public function findAuthor(int $id): ?array
    {
        $row = $this->connection->fetchAssociative('SELECT id, name FROM author WHERE id = :id', ['id' => $id]);

        return false === $row ? null : $row;
    }

    /**
     * @return list<array<string, mixed>>
     */
    public function publishedBooksOf(int $authorId): array
    {
        return $this->connection->fetchAllAssociative(
            'SELECT id, title FROM book WHERE author_id = :id AND published = true ORDER BY id',
            ['id' => $authorId],
        );
    }

    public function customerExists(int $id): bool
    {
        return false !== $this->connection->fetchOne('SELECT 1 FROM customer WHERE id = :id', ['id' => $id]);
    }

    public function countPurchases(int $customerId): int
    {
        return (int) $this->connection->fetchOne('SELECT COUNT(*) FROM purchase WHERE customer_id = :c', ['c' => $customerId]);
    }

    /**
     * @return list<array<string, mixed>>
     */
    public function purchasesPage(int $customerId, int $offset, int $limit): array
    {
        return $this->connection->fetchAllAssociative(
            'SELECT id, created_at, total_cents FROM purchase WHERE customer_id = :c '
            .'ORDER BY created_at DESC, id DESC LIMIT '.$limit.' OFFSET '.$offset,
            ['c' => $customerId],
        );
    }

    /**
     * @return array<string, mixed>|null
     */
    public function findPurchase(int $customerId, int $id): ?array
    {
        $row = $this->connection->fetchAssociative(
            'SELECT id, created_at, total_cents FROM purchase WHERE id = :id AND customer_id = :c',
            ['id' => $id, 'c' => $customerId],
        );

        return false === $row ? null : $row;
    }

    /**
     * @param list<int> $purchaseIds
     *
     * @return array<int, list<array<string, mixed>>> purchase id => lines
     */
    public function linesOf(array $purchaseIds): array
    {
        if ([] === $purchaseIds) {
            return [];
        }

        $rows = $this->connection->fetchAllAssociative(
            'SELECT pl.purchase_id, pl.book_id, b.title, pl.quantity, pl.unit_price_cents '
            .'FROM purchase_line pl JOIN book b ON b.id = pl.book_id '
            .'WHERE pl.purchase_id IN (:ids) ORDER BY pl.id',
            ['ids' => array_values($purchaseIds)],
            ['ids' => \Doctrine\DBAL\ArrayParameterType::INTEGER],
        );

        $lines = [];
        foreach ($rows as $row) {
            $lines[(int) $row['purchase_id']][] = $row;
        }

        return $lines;
    }

    /**
     * @return list<array<string, mixed>> sales per book: book_id, title, quantity, revenue_cents
     */
    public function salesBetween(\DateTimeImmutable $fromInclusive, \DateTimeImmutable $toExclusive): array
    {
        return $this->connection->fetchAllAssociative(
            'SELECT b.id AS book_id, b.title, SUM(pl.quantity) AS quantity, SUM(pl.quantity * pl.unit_price_cents) AS revenue_cents '
            .'FROM purchase_line pl '
            .'JOIN purchase p ON p.id = pl.purchase_id '
            .'JOIN book b ON b.id = pl.book_id '
            .'WHERE p.created_at >= CAST(:from AS timestamptz) AND p.created_at < CAST(:to AS timestamptz) '
            .'GROUP BY b.id, b.title '
            .'ORDER BY revenue_cents DESC, b.title ASC, b.id ASC',
            [
                'from' => $fromInclusive->format(DATE_ATOM),
                'to' => $toExclusive->format(DATE_ATOM),
            ],
        );
    }
}
