<?php

namespace App\Bookshop;

use Symfony\Component\HttpClient\Exception\TransportException;
use Symfony\Component\HttpKernel\Exception\BadGatewayHttpException;
use Symfony\Component\HttpKernel\Exception\HttpException;
use Symfony\Contracts\HttpClient\HttpClientInterface;

final class PaymentGateway
{
    public function __construct(
        private readonly HttpClientInterface $httpClient,
        private readonly string $paymentUrl,
    ) {
    }

    /**
     * @throws HttpException 402 when declined, 502 when the service fails or answers anything unexpected
     */
    public function charge(int $customerId, int $amountCents): void
    {
        try {
            $response = $this->httpClient->request('POST', $this->paymentUrl, [
                'json' => ['customerId' => $customerId, 'amountCents' => $amountCents],
                'timeout' => 5,
            ]);
            $status = $response->getStatusCode();
            $body = 200 === $status ? $response->toArray(false) : null;
        } catch (TransportException|\Throwable) {
            throw new BadGatewayHttpException('Payment service unavailable.');
        }

        $result = is_array($body) ? ($body['status'] ?? null) : null;
        if ('accepted' === $result) {
            return;
        }
        if ('declined' === $result) {
            throw new HttpException(402, 'Payment declined.');
        }

        throw new BadGatewayHttpException('Payment service returned an unexpected answer.');
    }
}
