<?php

namespace App\Bookshop;

use App\Api\Http\RequestInput;
use Doctrine\DBAL\ArrayParameterType;
use Doctrine\DBAL\Connection;
use Symfony\Component\HttpKernel\Exception\ConflictHttpException;
use Symfony\Component\HttpKernel\Exception\UnprocessableEntityHttpException;

final class PurchaseService
{
    public function __construct(
        private readonly Connection $connection,
        private readonly PaymentGateway $payments,
    ) {
    }

    /**
     * Buys the lines for a customer: locks the books, checks them, takes the payment and stores everything,
     * all in one transaction, so that a failure leaves nothing stored and no stock changed.
     *
     * @param list<array{bookId: int, quantity: int}> $lines
     *
     * @return int the new purchase id
     */
    public function place(int $customerId, array $lines): int
    {
        return $this->connection->transactional(function (Connection $c) use ($customerId, $lines): int {
            $quantities = [];
            foreach ($lines as $line) {
                $quantities[$line['bookId']] = ($quantities[$line['bookId']] ?? 0) + $line['quantity'];
            }
            ksort($quantities);

            $books = $c->fetchAllAssociativeIndexed(
                'SELECT id, price_cents, stock FROM book WHERE id IN (:ids) AND published = true ORDER BY id FOR UPDATE',
                ['ids' => array_keys($quantities)],
                ['ids' => ArrayParameterType::INTEGER],
            );

            foreach (array_keys($quantities) as $bookId) {
                if (!isset($books[$bookId])) {
                    throw new UnprocessableEntityHttpException(sprintf('Book %d is not available.', $bookId));
                }
            }
            foreach ($quantities as $bookId => $quantity) {
                if ($books[$bookId]['stock'] < $quantity) {
                    throw new ConflictHttpException(sprintf('Not enough stock for book %d.', $bookId));
                }
            }

            $total = 0;
            foreach ($lines as $line) {
                $total += $line['quantity'] * (int) $books[$line['bookId']]['price_cents'];
            }

            $this->payments->charge($customerId, $total);

            $purchaseId = (int) $c->fetchOne(
                'INSERT INTO purchase (customer_id, created_at, total_cents) VALUES (:c, now(), :total) RETURNING id',
                ['c' => $customerId, 'total' => $total],
            );

            foreach ($lines as $line) {
                $c->executeStatement(
                    'INSERT INTO purchase_line (purchase_id, book_id, quantity, unit_price_cents) VALUES (:p, :b, :q, :price)',
                    [
                        'p' => $purchaseId,
                        'b' => $line['bookId'],
                        'q' => $line['quantity'],
                        'price' => (int) $books[$line['bookId']]['price_cents'],
                    ],
                );
            }
            foreach ($quantities as $bookId => $quantity) {
                $c->executeStatement('UPDATE book SET stock = stock - :q WHERE id = :id', ['q' => $quantity, 'id' => $bookId]);
            }

            return $purchaseId;
        });
    }
}
