/**
 * @implements ProviderInterface<Page>
 */
final class PurchaseCollectionProvider implements ProviderInterface
{
    public function __construct(
        private readonly RequestStack $requestStack,
        private readonly BookshopStore $store,
    ) {
    }

    public function provide(Operation $operation, array $uriVariables = [], array $context = []): Page
    {
        $request = $this->requestStack->getCurrentRequest();
        $page = RequestInput::page($request);
        $itemsPerPage = RequestInput::itemsPerPage($request);
        $customerId = $request->attributes->getInt(CustomerAuthSubscriber::ATTRIBUTE);

        $total = $this->store->countPurchases($customerId);
        $offset = ($page - 1) * $itemsPerPage;
        $rows = $offset >= $total ? [] : $this->store->purchasesPage($customerId, $offset, $itemsPerPage);

        $linesByPurchase = $this->store->linesOf(array_map(static fn (array $row) => (int) $row['id'], $rows));
        $items = array_map(
            static fn (array $row) => PurchaseItem::fromRows($row, $linesByPurchase[(int) $row['id']] ?? []),
            $rows,
        );

        return new Page($items, $total, $page, $itemsPerPage);
    }
}
