<?php

namespace App\Api\Processor;

use ApiPlatform\Metadata\Operation;
use ApiPlatform\State\ProcessorInterface;
use App\Api\Dto\BookItem;
use App\Api\Http\RequestInput;
use App\Bookshop\BookshopStore;
use Symfony\Component\HttpFoundation\RequestStack;
use Symfony\Component\HttpKernel\Exception\UnprocessableEntityHttpException;

/**
 * Partial update of title, priceCents and stock. Answers 204 for unpublished books.
 *
 * @implements ProcessorInterface<mixed, BookItem|null>
 */
final class BookPatchProcessor implements ProcessorInterface
{
    public function __construct(
        private readonly RequestStack $requestStack,
        private readonly BookshopStore $store,
    ) {
    }

    public function process(mixed $data, Operation $operation, array $uriVariables = [], array $context = []): ?BookItem
    {
        $id = RequestInput::pathId($uriVariables['id'] ?? null);
        $body = RequestInput::jsonObject($this->requestStack->getCurrentRequest());

        $changes = [];
        if (array_key_exists('title', $body)) {
            $title = $body['title'];
            if (!is_string($title) || '' === trim($title)) {
                throw new UnprocessableEntityHttpException('title must be a non-empty string.');
            }
            $changes['title'] = $title;
        }
        foreach (['priceCents' => 'price_cents', 'stock' => 'stock'] as $field => $column) {
            if (array_key_exists($field, $body)) {
                $value = $body[$field];
                if (!is_int($value) || $value < 0 || $value > RequestInput::MAX_INT) {
                    throw new UnprocessableEntityHttpException(sprintf('%s must be a non-negative integer.', $field));
                }
                $changes[$column] = $value;
            }
        }

        $this->store->updateBook($id, $changes);
        $row = $this->store->findBook($id, false);

        return $row['published'] ? BookItem::fromRow($row) : null;
    }
}
