<?php

namespace App\Api\Processor;

use ApiPlatform\Metadata\Operation;
use ApiPlatform\State\ProcessorInterface;
use App\Api\Dto\PurchaseItem;
use App\Api\Http\RequestInput;
use App\Bookshop\BookshopStore;
use App\Bookshop\PurchaseService;
use App\EventSubscriber\CustomerAuthSubscriber;
use Symfony\Component\HttpFoundation\RequestStack;
use Symfony\Component\HttpKernel\Exception\UnprocessableEntityHttpException;

/**
 * @implements ProcessorInterface<mixed, PurchaseItem>
 */
final class PurchaseCreateProcessor implements ProcessorInterface
{
    public function __construct(
        private readonly RequestStack $requestStack,
        private readonly PurchaseService $purchases,
        private readonly BookshopStore $store,
    ) {
    }

    public function process(mixed $data, Operation $operation, array $uriVariables = [], array $context = []): PurchaseItem
    {
        $request = $this->requestStack->getCurrentRequest();
        $customerId = $request->attributes->getInt(CustomerAuthSubscriber::ATTRIBUTE);
        $lines = self::parseLines(RequestInput::jsonObject($request)['lines'] ?? null);

        $id = $this->purchases->place($customerId, $lines);
        $row = $this->store->findPurchase($customerId, $id);

        return PurchaseItem::fromRows($row, $this->store->linesOf([$id])[$id] ?? []);
    }

    /**
     * @return list<array{bookId: int, quantity: int}>
     */
    private static function parseLines(mixed $lines): array
    {
        if (!is_array($lines) || !array_is_list($lines) || [] === $lines) {
            throw new UnprocessableEntityHttpException('lines must be a non-empty list.');
        }

        $parsed = [];
        foreach ($lines as $line) {
            if (!is_array($line) || !is_int($line['bookId'] ?? null) || !is_int($line['quantity'] ?? null)) {
                throw new UnprocessableEntityHttpException('Each line needs an integer bookId and an integer quantity.');
            }
            if ($line['bookId'] < 1 || $line['bookId'] > RequestInput::MAX_INT) {
                throw new UnprocessableEntityHttpException('Unknown book.');
            }
            if ($line['quantity'] < 1 || $line['quantity'] > RequestInput::MAX_INT) {
                throw new UnprocessableEntityHttpException('quantity must be at least 1.');
            }
            $parsed[] = ['bookId' => $line['bookId'], 'quantity' => $line['quantity']];
        }

        return $parsed;
    }
}
