<?php

namespace App\EventSubscriber;

use App\Api\Http\RequestInput;
use Doctrine\DBAL\Connection;
use Symfony\Component\EventDispatcher\EventSubscriberInterface;
use Symfony\Component\HttpFoundation\JsonResponse;
use Symfony\Component\HttpKernel\Event\RequestEvent;
use Symfony\Component\HttpKernel\KernelEvents;

/**
 * Identifies the customer from X-Customer-Id before routing, so that every purchase request
 * answers 401 first, whatever else is wrong with it.
 */
final class CustomerAuthSubscriber implements EventSubscriberInterface
{
    public const ATTRIBUTE = 'bookshop_customer_id';

    public function __construct(private readonly Connection $connection)
    {
    }

    public static function getSubscribedEvents(): array
    {
        return [KernelEvents::REQUEST => ['authenticate', 64]];
    }

    public function authenticate(RequestEvent $event): void
    {
        $request = $event->getRequest();
        if (!$event->isMainRequest() || !preg_match('#^/purchases(/|$)#', $request->getPathInfo())) {
            return;
        }

        $customerId = RequestInput::customerId($request->headers->get('X-Customer-Id'));
        if (null === $customerId || false === $this->connection->fetchOne('SELECT 1 FROM customer WHERE id = :id', ['id' => $customerId])) {
            $event->setResponse(new JsonResponse(['error' => 'Unknown or missing customer.'], 401));

            return;
        }

        $request->attributes->set(self::ATTRIBUTE, $customerId);
    }
}
