<?php

namespace App\EventSubscriber;

use Symfony\Component\EventDispatcher\EventSubscriberInterface;
use Symfony\Component\HttpFoundation\JsonResponse;
use Symfony\Component\HttpFoundation\Response;
use Symfony\Component\HttpKernel\Exception\HttpExceptionInterface;
use Symfony\Component\HttpKernel\Event\ExceptionEvent;
use Symfony\Component\HttpKernel\KernelEvents;

/**
 * Every error answers {"error": "..."} with its status code.
 */
final class ApiErrorSubscriber implements EventSubscriberInterface
{
    public static function getSubscribedEvents(): array
    {
        return [KernelEvents::EXCEPTION => ['onException', 256]];
    }

    public function onException(ExceptionEvent $event): void
    {
        $throwable = $event->getThrowable();

        if ($throwable instanceof HttpExceptionInterface) {
            $status = $throwable->getStatusCode();
            $headers = $throwable->getHeaders();
            $message = $throwable->getMessage();
            if ('' === $message || str_starts_with($message, 'No route found')) {
                $message = Response::$statusTexts[$status] ?? 'Error';
            }
        } else {
            $status = 500;
            $headers = [];
            $message = 'Internal server error.';
        }

        $event->setResponse(new JsonResponse(['error' => $message], $status, $headers));
    }
}
