<?php

namespace App\Controller;

use App\Api\Http\RequestInput;
use App\Bookshop\BookshopStore;
use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\HttpFoundation\Response;
use Symfony\Component\HttpKernel\Exception\BadRequestHttpException;
use Symfony\Component\Routing\Attribute\Route;

final class SalesReportController
{
    public function __construct(private readonly BookshopStore $store)
    {
    }

    #[Route('/reports/sales', name: 'reports_sales', methods: ['GET'])]
    public function __invoke(Request $request): Response
    {
        $from = RequestInput::requiredDate($request, 'from');
        $to = RequestInput::requiredDate($request, 'to');
        if ($from > $to) {
            throw new BadRequestHttpException('from must not be after to.');
        }

        $utc = new \DateTimeZone('UTC');
        $rows = $this->store->salesBetween(
            new \DateTimeImmutable($from.' 00:00:00', $utc),
            (new \DateTimeImmutable($to.' 00:00:00', $utc))->modify('+1 day'),
        );

        $handle = fopen('php://temp', 'r+');
        fputcsv($handle, ['title', 'quantity', 'revenueCents']);
        foreach ($rows as $row) {
            fputcsv($handle, [$row['title'], (int) $row['quantity'], (int) $row['revenue_cents']]);
        }
        rewind($handle);
        $csv = stream_get_contents($handle);
        fclose($handle);

        return new Response($csv, 200, [
            'Content-Type' => 'text/csv; charset=UTF-8',
            'Content-Disposition' => sprintf('attachment; filename="sales-%s-%s.csv"', $from, $to),
        ]);
    }
}
